package app.sleepscreen.tv;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.provider.Settings;import android.graphics.Color;import android.widget.*;
public class SetupActivity extends Activity {
 protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,48),Ui.dp(this,30),Ui.dp(this,48),Ui.dp(this,30));root.setBackgroundColor(0xff0b0d12);TextView title=Ui.text(this,30,Color.WHITE);title.setText("Set up Sleep Screen");root.addView(title);TextView text=Ui.text(this,17,0xffdddddd);text.setText("1. Enable Sleep Screen in Accessibility so the timer can put your device to sleep and display the countdown and screen filters.\n\n2. Allow display over other apps for timer warnings.\n\n3. Allow alarms and reminders if your device offers the option.\n\nOptional: enable Sleep Screen Remote in Accessibility to map a remote button. It can observe button presses but does not read screen content. Other button mappers may conflict.\n\nAndroid may require Allow restricted settings for sideloaded apps.");root.addView(text);TextView a=Ui.row(root,650);a.setText("Open accessibility settings");a.setOnClickListener(v->open(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));TextView info=Ui.row(root,650);info.setText("Open Sleep Screen app info");info.setOnClickListener(v->open(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));TextView o=Ui.row(root,650);o.setText("Allow display over other apps");o.setOnClickListener(v->open(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));TextView alarm=Ui.row(root,650);alarm.setText("Allow alarms and reminders");alarm.setOnClickListener(v->open(new Intent("android.settings.REQUEST_SCHEDULE_EXACT_ALARM",Uri.parse("package:"+getPackageName()))));TextView map=Ui.row(root,650);map.setText("Configure remote button");map.setOnClickListener(v->startActivity(new Intent(this,MapperActivity.class)));ScrollView sc=new ScrollView(this);sc.addView(root);setContentView(sc);a.requestFocus();}
 private void open(Intent i){try{startActivity(i);}catch(Exception e){Toast.makeText(this,"This settings page is not available on this device",Toast.LENGTH_LONG).show();}}
}